  "Horário atual da biblioteca": { en: "Current library time", es: "Hora actual de la biblioteca", de: "Aktuelle Uhrzeit der Bibliothek", fr: "Heure actuelle de la bibliothèque", it: "Ora attuale della biblioteca" },
  "Solicite a ficha ainda assim. Analisaremos no próximo dia útil": { en: "You can still request the record. We will review it on the next business day", es: "Solicite la ficha de todos modos. La revisaremos el próximo día hábil", de: "Beantragen Sie die Karte trotzdem. Wir prüfen sie am nächsten Werktag", fr: "Demandez tout de même la notice. Nous l’examinerons le prochain jour ouvré", it: "Richiedi comunque la scheda. La esamineremo il prossimo giorno lavorativo" },
