  "Enviar link para alterar senha": { en: "Send password change link", es: "Enviar enlace para cambiar contraseña", de: "Link zum Ändern des Passworts senden", fr: "Envoyer le lien de changement de mot de passe", it: "Invia link per modificare la password" },
