  "Correção de dados": { en: "Correcting information", es: "Corrección de datos", de: "Korrektur von Angaben", fr: "Correction des données", it: "Correzione dei dati" },
  "Nada Consta": { en: "Nada Consta", es: "Nada Consta", de: "Nada Consta", fr: "Nada Consta", it: "Nada Consta" },
