  "Currículo Lattes e ORCID": { en: "Lattes CV and ORCID", es: "Currículo Lattes y ORCID", de: "Lattes-Lebenslauf und ORCID", fr: "CV Lattes et ORCID", it: "Curriculum Lattes e ORCID" },
