  "Faculdade, instituto ou departamento": { en: "Faculty, institute or department", es: "Facultad, instituto o departamento", de: "Fakultät, Institut oder Fachbereich", fr: "Faculté, institut ou département", it: "Facoltà, istituto o dipartimento" },
  "Nome do curso": { en: "Course name", es: "Nombre del curso", de: "Name des Studiengangs", fr: "Nom du cursus", it: "Nome del corso" },
  "Nome do programa de pós-graduação": { en: "Graduate program name", es: "Nombre del programa de posgrado", de: "Name des Graduiertenprogramms", fr: "Nom du programme de deuxième cycle", it: "Nome del programma post laurea" },
